    required this.id,
    required this.function,
    this.encryptedValue,
    this.metadata,
  });

  /// Decodes a document; throws [AguiDecodeException] when it does not match.
  factory ToolCall.fromJson(Map<String, Object?> json) {
    const definition = 'ToolCall';
    _literal(json['type'], 'function', definition, '/type');
    _require(json, definition, 'id');
    _require(json, definition, 'function');
    return ToolCall(
      id: _string(json['id'], definition, '/id'),
      function: FunctionCall.fromJson(
        _object(json['function'], definition, '/function'),
      ),
      encryptedValue: _opt(
        json,
        'encryptedValue',
        (v) => _string(v, definition, '/encryptedValue'),
      ),
      metadata: _opt(
        json,
        'metadata',
        (v) => _openMap(v, definition, '/metadata'),
      ),
    );
  }

  /// The only kind of call the protocol models.
  String get type => 'function';

  /// Identifies the call. The answering tool message carries this as its
  /// toolCallId.
  final String id;

  /// What is being called, and with what.
  final FunctionCall function;

  /// A provider's opaque artefact belonging to this call.
  final String? encryptedValue;

  /// Extra information attached to this call. Carried here rather than folded
  /// into the containing message, because several calls can share one parent
  /// and merging them would make the result depend on their order.
  final Metadata? metadata;

  /// The wire form of this value.
  Map<String, Object?> toJson() => {
    'type': type,
    'id': id,
    'function': function.toJson(),
    if (encryptedValue != null) 'encryptedValue': encryptedValue,
    if (metadata != null) 'metadata': metadata,
  };
}

