/// Every role a materialised message may have.
enum Role {
  developer('developer'),
  system('system'),
  assistant('assistant'),
  user('user'),
  tool('tool'),
  activity('activity'),
  reasoning('reasoning');

  const Role(this.wireName);

  /// The value as it appears on the wire.
  final String wireName;

  /// The member for a wire value, or null when there is none.
  static Role? tryFromWire(String wire) {
    for (final member in values) {
      if (member.wireName == wire) return member;
    }
    return null;
  }

  /// The member for a wire value; an unknown value is a decode error.
  static Role fromWire(Object? value, String definition, String path) {
    final wire = _string(value, definition, path);
    return tryFromWire(wire) ??
        _fail(definition, path, 'unknown Role value "$wire"');
  }
}

