final class HumanInTheLoopCapabilities {
  const HumanInTheLoopCapabilities({
    this.supported,
    this.approvals,
    this.interventions,
    this.feedback,
    this.interrupts,
    this.approveWithEdits,
  });

  /// Decodes a document; throws [AguiDecodeException] when it does not match.
  factory HumanInTheLoopCapabilities.fromJson(Map<String, Object?> json) {
    const definition = 'HumanInTheLoopCapabilities';
    return HumanInTheLoopCapabilities(
      supported: _opt(
        json,
        'supported',
        (v) => _bool(v, definition, '/supported'),
      ),
      approvals: _opt(
        json,
        'approvals',
        (v) => _bool(v, definition, '/approvals'),
      ),
      interventions: _opt(
        json,
        'interventions',
        (v) => _bool(v, definition, '/interventions'),
      ),
      feedback: _opt(
        json,
        'feedback',
        (v) => _bool(v, definition, '/feedback'),
      ),
      interrupts: _opt(
        json,
        'interrupts',
        (v) => _bool(v, definition, '/interrupts'),
      ),
      approveWithEdits: _opt(
        json,
        'approveWithEdits',
        (v) => _bool(v, definition, '/approveWithEdits'),
      ),
    );
  }

  /// Set true if the agent supports any form of human-in-the-loop interaction.
  final bool? supported;

  /// Set true if the agent can pause and request explicit approval before
  /// performing sensitive actions (e.g., sending emails, deleting data).
  final bool? approvals;

  /// Set true if the agent allows humans to intervene and modify its plan
  /// mid-execution.
  final bool? interventions;

  /// Set true if the agent can incorporate user feedback (thumbs up/down,
  /// corrections) to improve its behavior within the current session.
  final bool? feedback;

  /// Set true if the agent participates in the AG-UI interrupt protocol: it
  /// ends a run with RUN_FINISHED carrying an interrupt outcome, and accepts
  /// the answers back in RunAgentInput.resume.
  final bool? interrupts;

  /// Set true if tool-call interrupts accept editedArgs in the resume payload.
  /// Only meaningful when interrupts is true.
  final bool? approveWithEdits;

  /// The wire form of this value.
  Map<String, Object?> toJson() => {
    if (supported != null) 'supported': supported,
    if (approvals != null) 'approvals': approvals,
    if (interventions != null) 'interventions': interventions,
    if (feedback != null) 'feedback': feedback,
    if (interrupts != null) 'interrupts': interrupts,
    if (approveWithEdits != null) 'approveWithEdits': approveWithEdits,
  };
}

/// A typed, categorized snapshot of an agent's current capabilities. All fields
/// are optional — agents only declare what they support. An omitted field means
/// the capability is not declared (unknown), not that it is unsupported. The
/// custom field is an escape hatch for integration-specific capabilities that
/// do not fit into the standard categories.
final class AgentCapabilities {
  const AgentCapabilities({
    this.identity,
    this.transport,
    this.tools,
    this.output,
    this.state,
    this.multiAgent,
    this.reasoning,
    this.multimodal,
    this.execution,
    this.humanInTheLoop,
    this.custom,
  });

  /// Decodes a document; throws [AguiDecodeException] when it does not match.
  factory AgentCapabilities.fromJson(Map<String, Object?> json) {
    const definition = 'AgentCapabilities';
    return AgentCapabilities(
      identity: _opt(
        json,
        'identity',
        (v) =>
            IdentityCapabilities.fromJson(_object(v, definition, '/identity')),
      ),
      transport: _opt(
        json,
        'transport',
        (v) => TransportCapabilities.fromJson(
          _object(v, definition, '/transport'),
        ),
      ),
      tools: _opt(
        json,
        'tools',
        (v) => ToolsCapabilities.fromJson(_object(v, definition, '/tools')),
      ),
      output: _opt(
        json,
        'output',
        (v) => OutputCapabilities.fromJson(_object(v, definition, '/output')),
      ),
      state: _opt(
        json,
        'state',
        (v) => StateCapabilities.fromJson(_object(v, definition, '/state')),
      ),
      multiAgent: _opt(
        json,
        'multiAgent',
        (v) => MultiAgentCapabilities.fromJson(
          _object(v, definition, '/multiAgent'),
        ),
      ),
      reasoning: _opt(
        json,
        'reasoning',
        (v) => ReasoningCapabilities.fromJson(
          _object(v, definition, '/reasoning'),
        ),
      ),
      multimodal: _opt(
        json,
        'multimodal',
        (v) => MultimodalCapabilities.fromJson(
          _object(v, definition, '/multimodal'),
        ),
      ),
      execution: _opt(
        json,
        'execution',
        (v) => ExecutionCapabilities.fromJson(
          _object(v, definition, '/execution'),
        ),
      ),
      humanInTheLoop: _opt(
        json,
        'humanInTheLoop',
        (v) => HumanInTheLoopCapabilities.fromJson(
          _object(v, definition, '/humanInTheLoop'),
        ),
      ),
      custom: _opt(json, 'custom', (v) => _openMap(v, definition, '/custom')),
    );
  }

  /// Agent identity and metadata.
  final IdentityCapabilities? identity;

  /// Supported transport mechanisms (SSE, WebSocket, binary, etc.).
  final TransportCapabilities? transport;

  /// Tools the agent provides and tool calling configuration.
  final ToolsCapabilities? tools;

  /// Output format support (structured output, MIME types).
  final OutputCapabilities? output;

  /// State and memory management (snapshots, deltas, persistence).
  final StateCapabilities? state;

  /// Multi-agent coordination (delegation, handoffs, subagents).
  final MultiAgentCapabilities? multiAgent;

  /// Reasoning and thinking support (chain-of-thought, encrypted thinking).
  final ReasoningCapabilities? reasoning;

  /// Multimodal input/output support (images, audio, video, files).
  final MultimodalCapabilities? multimodal;

  /// Execution control and limits (code execution, timeouts, iteration caps).
  final ExecutionCapabilities? execution;

  /// Human-in-the-loop support (approvals, interventions, feedback).
  final HumanInTheLoopCapabilities? humanInTheLoop;

  /// Integration-specific capabilities not covered by the standard categories.
  /// Open by key: any JSON value is allowed under a key, because the categories
  /// above cannot anticipate what an integration declares.
  final Map<String, Object?>? custom;

  /// The wire form of this value.
  Map<String, Object?> toJson() => {
    if (identity != null) 'identity': identity?.toJson(),
    if (transport != null) 'transport': transport?.toJson(),
    if (tools != null) 'tools': tools?.toJson(),
    if (output != null) 'output': output?.toJson(),
    if (state != null) 'state': state?.toJson(),
    if (multiAgent != null) 'multiAgent': multiAgent?.toJson(),
    if (reasoning != null) 'reasoning': reasoning?.toJson(),
    if (multimodal != null) 'multimodal': multimodal?.toJson(),
    if (execution != null) 'execution': execution?.toJson(),
    if (humanInTheLoop != null) 'humanInTheLoop': humanInTheLoop?.toJson(),
    if (custom != null) 'custom': custom,
  };
}
